(12, 12, 2, 0, '2023-09-07', 4001659, 'Gustavo Lomazzo', '4342-REQ - Ingeniería y provisión de vigas metálicas para puente grua 25Ton', 'Vigas reticuladas de 24m de LUZ para soportar puente grúa de 25Ton, vigas monolíticas, de sección T, formadas por perfiles  laminados HyL soldados.', 1, 212000, 1, '', 1, 0, 0, 4, '2024-11-20 15:06:00', NULL, NULL),
(13, 13, 2, 0, '2024-01-19', 4001789, 'Agustin Pinski', 'Pecon.Ched-UTE', 'Provisión de anclaje para proyecto Sal de Vida', 1, 32654.96, 1, '', 1, 0, 0, 4, '2024-11-29 16:28:36', NULL, NULL),
(14, 14, 2, 0, '2024-04-26', 4001659, 'Gustavo Lomazzo', '4550 REQ - Entramado Metálico', 'Tenemos el agrado de cotizar a Uds. los trabajos de provisión de conjuntos de marco y rejas en todo de acuerdo a vuestro pedido, especificaciones técnicas y el siguiente detalle:\r\n\r\nCada conjunto estará formado por perfil L de apoyo y ocho rejillas electrosoldadas de acuerdo a la documentación recibida y una sobrecarga de 500kg/m2\r\n\r\nEl material será calidad F24, galvanizado en caliente\r\n\r\nSe incluye relevamiento y ajuste de ingeniería\r\n\r\nLa entrega será en vuestra planta de Dock Sud\r\n', 1, 197600, 1, 'Certificación:			anticipo 50%, saldo contra cada entrega\r\nForma de pago: 		e-cheq 15 días – se emitirá NC/ND por DF a la fecha de pago\r\nPlazo de entrega: 		60 días con entregas parciales\r\nValidez de la oferta: 		10 días', 8, 1, 0, 4, '2025-02-19 10:48:33', NULL, NULL),
(15, 14, 1, 0, '2025-02-20', 4001579, 'Agustin Pinski', 'Pecon.Ched-UTE', 'Provisión de anclaje para proyecto Sal de Vida', 1, 2000, 1, '', 2, 1, 0, 4, '2025-02-20 09:12:05', NULL, NULL),
(16, 14, 1, 1, '2025-02-20', 4001579, 'Agustin Pinski', 'Pecon.Ched-UTE', 'Provisión de anclaje para proyecto Sal de Vida', 1, 2001, 1, '', 2, 0, 0, 4, '2025-02-20 09:12:05', 'el cliente ,,,', '2025-02-20 09:17:27'),
(17, 17, 2, 0, '2025-03-13', 4001659, 'Gustavo Lomazzo', '4342-REQ - Ingeniería y provisión de vigas metálicas para puente grua 25Ton', 'Vigas reticuladas de 24m de LUZ para soportar puente grúa de 25Ton, vigas monolíticas, de sección T, formadas por perfiles  laminados HyL soldados.', 1, 40400, 0, '', 2, 0, 1, 4, '2025-03-13 09:06:13', NULL, NULL),
(18, 18, 2, 0, '2025-03-13', 4001659, 'Gustavo Lomazzo', '4342-REQ - Ingeniería y provisión de vigas metálicas para puente grua 25Ton', 'Vigas reticuladas de 24m de LUZ para soportar puente grúa de 25Ton, vigas monolíticas, de sección T, formadas por perfiles  laminados HyL soldados.', 1, 5555, 1, '', 2, 0, 0, 4, '2025-03-13 09:07:12', NULL, NULL),
(19, 19, 1, 0, '2025-03-13', 5002171, 'nelñson', 'ALGO', 'LJK', 2, 10, 0, '', 2, 0, 0, 2, '2025-03-13 09:11:57', NULL, NULL),
