INSERT INTO `proyectos` (`id`, `id_sitio`, `descripcion`, `id_tipo_proyecto`, `observaciones`, `solicitante`, `fecha_pedido`, `fecha_entrega`, `id_estado_proyecto`, `id_usuario`, `informacion_entrada`, `facturado`, `id_gerente`, `id_linea_negocio`, `anulado`, `id_cliente`, `nombre`, `tags`, `nro`) VALUES
(1, 6462, 'Diseño, ingeniería, fabricación y supervisión de montaje de un puente grúa birriel de 7.5 ton de ca', 7, '', 'Abba Montana', '2024-06-13', '0000-00-00', 2, 9, '', NULL, 4001263, 4, 0, 4001911, 'Provisión de puente grúa', 'Pluspe', 0),
(2, 2, 'Prov de 2 vigas reticuladas de 24m de luz para soportar pte grúa de 25tn. Serán monolíticas, de sec', 7, '', 'Gustavo Lomazzo', '2023-09-14', '2023-11-14', 2, 1, '', NULL, 4001263, 3, 0, 4001659, 'Provisión de Vigas para puente Grúa', 'Fisia-AA', 0),
(3, 2, 'Ingeniería, provisión, ensayo y montaje de soporte sistema de bombeo, formado por   pontón vinculad', 7, '', 'Gustavo Lomazzo', '2024-07-24', '2024-08-07', 2, 9, 'PPTO NET 2962 / OC 4200079753', NULL, 4001900, 4, 1, 4001659, 'Pontón y Pasarela', 'Balsa, Pasarela.', 0),
(4, 6413, 'Ingeniería y fabricación de sala eléctrica que se fabricará de un contenedor marítimo reciclado. Se', 5, '', 'Luis Correa', '2024-07-02', '2024-11-01', 2, 9, 'PPTO NET 3288 / OC 00013659 Rev001', NULL, 4001900, 5, 1, 4001458, 'Sala Eléctrica', 'Sala, Shelter, Contenedor', 0),
(5, 6413, 'Ingeniería y fabricación de sala eléctrica que se fabricará de un contenedor marítimo reciclado. Se', 5, '', 'Luis Correa', '2024-07-02', '2024-10-02', 2, 9, '', NULL, 4000014, 5, 1, 4001458, 'Contenedor para Sala Eléctrica', 'Sala, contenedor', 0),
(6, 6465, 'Ingeniería, fabricación y certificación de una percha de 30t, 5.35m de longitud. Con 2 cáncamos de Izaje superiores y 3 inferiores. Fabricada según plano recibido, pintada con el esquema indicado. Entrega en NET', 5, '', 'Matías Suarez', '2024-07-15', '2024-08-28', 2, 9, 'PPTO NET 3121 Rev.4 / OC 4600003390', NULL, 4001900, 5, 0, 4001894, 'Provisión de Percha 30t', 'Contenedor, Salas', 1),
(7, 6451, 'Ingeniería, provisión, ensayo y montaje de soporte sistema de bombeo, formado por   pontón vinculada a tierra mediante una pasarela arriostrada lateralmente a la costa.', 7, '', 'Gustavo Lomazzo', '2023-06-15', '2023-08-15', 2, 9, 'PPTO NET 2962 / OC 4200079753', NULL, 5002133, 4, 1, 4001659, 'Pontón y Pasarela', 'Ponton; Pasarela;', 1),
(8, 6446, 'Incluye la ingeniería de fabricación, ingeniería de montaje, provisión y entrega en obra de estructuras y misceláneos.  El tratamiento superficial podría ser galvanizado o pintado para cada caso.  Material F24 o F36  Entrega en Catamarca', 5, '', 'Sebastián Aldana', '2023-09-26', '2023-12-26', 2, 24, 'PPTO NET 3007 Rev. 2', NULL, 4001900, 4, 0, 4001789, 'Escalera Acceso Norte Filtro 3100 FL- 021', 'Estructuras', 1),
(9, 6469, 'Provisión de los soportes de playa de referencia en todo de acuerdo a vuestro pedido y el siguiente detalle  Se fabricarán de acuerdo a la ingeniería básica recibida, desarrollando nosotros la ingeniería de detalle.  Perfiles calidad F24 y F26 Chapas F24', 5, '', 'Daniel Paez', '2024-09-18', '2024-10-18', 4, 9, 'PPTO 3355 – Rev. 1/ OC 9100007705', NULL, 4001263, 4, 0, 3000178, 'Soportes de Playa ET Anchoris', 'Soportes', 1),
(10, 6474, 'Provisión de accesorios para filtro manga', 3, '', 'Luis Gómez', '2024-10-28', '2024-11-11', 2, 9, 'PPTO NET 3361 Rev.2 / OC Pendiente', NULL, 4001263, 4, 0, 5002169, 'Provisión de Accesorios', 'Accesorios / Filtro ', 1),
(11, 6446, 'Contempla la provisión de 835 pernos de anclaje de diferentes características según planos recibidos. El material de los pernos será calidad SAE 1026 o 1040 según corresponda. Entrega en NET en conjuntos armados.', 3, '', 'Agustín Pinski', '2024-12-02', '2025-01-02', 1, 9, 'PPTO NET 3130 Rev2/NP102201847', NULL, 5001651, 4, 0, 4001789, 'Provisión de Pernos', 'Pernos, Anclajes', 2),
(12, 6477, 'Fabricación y montaje de 2 escaleras metálicas según especificaciones técnicas recibidas.  Galvanizadas en caliente. Incluye bulonería galvanizada. Entregado en planta del cliente (Tigre)', 7, '', 'German Nistal', '2024-11-28', '2024-12-31', 2, 9, 'PPTOS: NET 3413 y NHC 5855 / OC GN00027452 y GN00027453', NULL, 4001263, 4, 0, 4000205, 'Escaleras Isla Martín Garcia', 'Escaleras, Islas, Agua', 1),
(13, 6478, 'Ingeniería y fabricación de una pasarela que será levantada con una grúa de forma excéntrica. Será de capacidad de 500kg en uno de sus extremos y en el otro tendrá contrapeso para equilibrarla. Pintado con esmalte sintético. Entrega en represa Ituzaingó', 5, '', 'Luciana Garau', '2025-01-24', '2025-02-25', 2, 9, 'PPTO NET Nº 3231 – Rev. 2 / OC 107235', NULL, 4001263, 4, 0, 5002170, 'Provisión de plataforma contrapesada', 'Plataforma, Guindola, Pasarela, Contrapesada', 1),
(14, 6451, 'Relev de ajuste, ingeniería y fabricación de conjuntos de marco y rejas según documentación recibida. Estarán formados por perfil L de apoyo y ocho rejillas electrosoldadas  (sobrecarga de 500kg/m2)', 5, '', 'Gustavo Lomazzo', '2024-04-26', '2025-02-19', 1, 8, '', NULL, 4001263, 4, 0, 4001659, 'Marco y entramado metálico (CS)', 'Marco y entramado metálico', 2),
(15, 6479, 'Verificación, ingeniería y fabricación de UN módulo galvanizado de 1.20m de lado y 0.30m de altura, sobre los cuales se colocaran vidrios de 20mm de espesor (no incluidos).  Provisión de anclajes y plantilla para construcción de las fundaciones', 5, '', 'Carola Zech', '2025-02-19', '2025-03-14', 2, 9, 'PPTO NHC 5853 – Rev. 1', NULL, 4001263, 3, 0, 4001130, 'Soportes para vidrios - Obra de Arte', 'Soportes', 1),
(16, 6480, 'Provisión e instalación de soportes (incluyendo grampas y anclajes) necesarios para el montaje del proyecto 6165-1-1.', 7, '', 'Gustavo Lomazzo', '2025-03-05', '2025-04-04', 2, 9, 'PPTO NHC 5903 / OC 4200081992', NULL, 4001263, 4, 0, 4001659, 'Fabricación y montaje de soportes para cañerías', 'Soportes, Spools, Cañerías', 1),
(17, 6481, 'Provisión de accesorios para camioneta Toyota Hilux y vallas de seguridad. Entrega en NET', 5, '', 'MM', '2025-03-13', '2025-05-13', 2, 9, 'PPTO NET 3531 Rev.1 / OC 848', NULL, 4001263, 4, 0, 3000125, 'Adecuación de patrullas y vallas de seguridad', 'Vallas, Patrullas', 1),
(18, 6482, 'proyecto prueba nelson', 1, '', 'nelson', '2025-03-14', '0000-00-00', 1, 1, '', NULL, 4001692, 2, 0, 5002171, 'proyecto prueba nelson', 'nelson', 1),
(19, 6451, 'Provisión de 9 conjuntos de Rejas con Marco, con diferentes características. Cada conjunto estará formado por perfil L de apoyo y rejas de planchuelas. F24, galvanizado en caliente. Enetrega en obra', 5, '', 'Gustavo Lomazzo', '2025-01-27', '2025-02-27', 2, 9, 'NH NET 3456 – Rev. 1 / OC 4100950212', NULL, 4001263, 4, 0, 4001659, 'REJAS', 'Rejas', 3),
(20, 6451, 'marcos y rejas', 5, '', 'Gustavo', '2025-03-14', '2025-03-21', 2, 9, 'ppto 1', NULL, 5001651, 4, 0, 4001659, 'Provisión de Marcos y rejas', 'rejas', 4),
(21, 6451, 'Provisión de 5 conjuntos de marco y rejas de diferentes dimensiones. Cada conjunto estará formado por perfil L de apoyo y rejas de planchuelas. Material calidad F24, galvanizado en caliente Entrega en obra Fisia.', 5, '', 'Gustavo Lomazzo', '2025-03-05', '2025-04-04', 2, 9, 'PPTO NET 3516 Rev 2 / OC 4200081981', NULL, 4001263, 4, 0, 4001659, 'Marcos y Rejillas para canaletas para EEE y TA', 'Rejillas', 5),
(22, 6483, 'Provisión de 4 moldes compuestos por un cilindro de 0.88m de diámetro y 2.45m de alto fabricado en chapa de 3.3mm de espesor con refuerzos de HR ADN 10mm y caño de 50x3mm. Calidad F24 sin terminación superficial. Entrega en NET', 5, '', 'Eduardo Servetti', '2025-03-28', '2025-04-14', 2, 9, 'PPTO NET 3528 / 4500657771', NULL, 4001263, 4, 0, 4000502, 'Provisión de Moldes para Noyos', 'Moldes', 1),
(23, 6451, 'Fabricación de Marcos y Tapas', 5, '', 'Gustavo Lomazzo', '2024-08-01', '2024-11-30', 1, 8, '', NULL, 4001263, 3, 0, 4001659, 'Marcos y Tapas', 'Marcos y Tapas', 6),
(24, 6484, 'muuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuuucho texto', 5, '', 'Diego Dias', '2025-04-29', '2025-05-29', 2, 1, 'PPTO NET 3569 / OC 091996', NULL, 5001651, 4, 0, 4001026, 'Provision de portones y puerta', 'Puertas, Portones', 1),
